  const section=E('section',null,'wb-panel wb-no-print');section.innerHTML='<h2>作品、版本与版面调整</h2><div class="wb-row"><button id="design-undo">撤销</button><button id="design-redo">重做</button><input id="design-name" maxlength="80" placeholder="作品或版本名称" aria-label="作品名称"><button id="design-save">保存为独立作品 / 新版本</button><select id="design-list" aria-label="已保存作品"></select><button id="design-load">载入所选版本</button><button id="design-delete">删除所选版本</button><button id="design-backup">导出全部作品</button><label>恢复作品库<input id="design-import" type="file" accept=".json"></label></div><div class="wb-row"><label><input id="design-drag" type="checkbox">显示拖动把手</label><label><input id="design-snap" type="checkbox" checked>吸附到统一网格</label><label><input id="design-safe" type="checkbox">显示安全区</label><label>预览比例<select id="design-ratio"><option value="native">原始比例</option><option value="16/9">16:9</option><option value="4/3">4:3</option><option value="9/16">9:16</option></select></label><button id="design-reset">重置自定义位置</button></div><p class="wb-note">位置调整会保存到当前作品，并包含在原生完整备份中。把手和安全区只用于编辑，不进入图片导出；大屏全屏时自动隐藏。作品库使用本机独立存储，不能替代下载备份。不同预览比例仅用于检查，海报实际尺寸仍由画布比例决定。</p><p id="design-status" class="wb-status" role="status"></p>';
  const main=document.querySelector('main');const bar=main.querySelector(':scope>.intro')||main.querySelector('.wb-bar');if(bar)bar.after(section);else main.prepend(section);const rows=[...section.querySelectorAll(':scope>.wb-row')],short=E('div',null,'wb-row'),details=E('details',null,'wb-more');details.id='design-options';details.append(E('summary','作品版本、拖动与预览设置'));short.append(rows[0].querySelector('#design-undo'),rows[0].querySelector('#design-redo'));for(const row of rows)details.append(row);details.append(section.querySelector('.wb-note'));section.querySelector('h2').after(short,details);
