  function trimHistory(){while(undo.length>20||undo.length>1&&JSON.stringify(undo).length>16*1048576)undo.shift();while(redo.length>20||redo.length>1&&JSON.stringify(redo).length>16*1048576)redo.shift();}function buttons(){trimHistory();$('design-undo').disabled=!undo.length;$('design-redo').disabled=!redo.length;}
  async function replace(v){if(restoring)throw Error('正在更新作品');restoring=true;try{await api.restore(copy(v));last=copy(api.state());}finally{restoring=false;buttons();positions();}}
