  function db(){return new Promise((resolve,reject)=>{const r=indexedDB.open('yj-design-library-v1.html',1);r.onupgradeneeded=()=>r.result.createObjectStore('projects',{keyPath:'id'});r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
  async function store(mode,fn){const d=await db();try{return await new Promise((resolve,reject)=>{const tx=d.transaction('projects',mode),r=fn(tx.objectStore('projects'));let value;r.onsuccess=()=>{value=r.result;};tx.oncomplete=()=>resolve(value);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error);});}finally{d.close();}}
  let library=[];async function list(){library=(await store('readonly',s=>s.getAll())).filter(x=>x.tool===slug).sort((a,b)=>b.updated-a.updated);$('design-list').replaceChildren();for(const x of library)$('design-list').add(new Option(x.name+' · '+new Date(x.updated).toLocaleString('zh-CN'),x.id));}
