  $('design-load').onclick=action(async()=>{const x=library.find(x=>x.id===$('design-list').value);if(!x)throw Error('请选择版本');if(!confirm('载入版本会替换当前作品，可用撤销返回。是否继续？'))return;const before=copy(api.state());await replace(x.value);undo.push(before);redo=[];buttons();message('版本已载入。');});
  $('design-delete').onclick=action(async()=>{const id=$('design-list').value;if(!id||!confirm('删除所选本地版本？请先下载需要的作品备份。'))return;await store('readwrite',s=>s.delete(id));await list();message('所选版本已删除，已下载备份不受影响。');});
  function download(v,name){const u=URL.createObjectURL(new Blob([JSON.stringify(v)],{type:'application/json'})),a=E('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),30000);}
  $('design-backup').onclick=action(async()=>{await list();download({app:'yj-design-library',version:1,tool:slug,projects:library},slug+'-全部作品.json');message('已发起全部作品下载。');});
  $('design-import').onchange=action(async()=>{const f=$('design-import').files[0];try{if(!f||f.size>32*1048576)throw Error('请选择 32 MB 内作品库备份');const v=JSON.parse(await f.text());if(v.app!=='yj-design-library'||v.version!==1||v.tool!==slug||!Array.isArray(v.projects)||v.projects.length>30)throw Error('作品库格式不匹配');const validated=v.projects.map(x=>{if(typeof x.name!=='string'||x.name.length>80)throw Error('作品名称无效');return {id:crypto.randomUUID(),tool:slug,name:x.name,updated:Date.now(),value:api.validate(x.value)};});const all=await store('readonly',s=>s.getAll());if(all.filter(x=>x.tool===slug).length+validated.length>30||JSON.stringify(all).length+JSON.stringify(validated).length>32*1048576)throw Error('合并后超出作品库上限，请先备份并清理旧版本');if(!confirm(`将新增 ${validated.length} 个版本，不替换现有作品。继续？`))return;const d=await db();try{await new Promise((resolve,reject)=>{const tx=d.transaction('projects','readwrite');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);for(const x of validated)tx.objectStore('projects').put(x);});}finally{d.close();}await list();message('作品库已合并恢复。');}finally{$('design-import').value='';}});
  const surface=slug==='poster'?document.querySelector('.studio-paper'):document.getElementById('stage');surface.classList.add('wb-design-surface');surface.style.position='relative';const safe=E('div',null,'wb-safe-zone');safe.hidden=true;safe.setAttribute('aria-hidden','true');surface.append(safe);const handles=[];const groups=slug==='poster'?['text','body','footer','logo','qr']:['text','support'];const bases=slug==='poster'?{text:[20,15],body:[20,45],footer:[20,85],logo:[82,10],qr:[78,80]}:{text:[45,30],support:[75,80]};
  for(const key of groups){const h=E('button',{text:'文字',body:'正文',footer:'页脚',logo:'Logo',qr:'二维码',support:'二维码与时钟'}[key],'wb-handle');h.type='button';h.hidden=true;surface.append(h);handles.push({key,h});let drag;
    h.onpointerdown=e=>{e.preventDefault();const value=copy(api.state()),layout=value.layout||{},p=layout[key]||{x:0,y:0},r=(slug==='poster'?document.getElementById('poster'):surface).getBoundingClientRect(),parent=surface.getBoundingClientRect();drag={x:e.clientX,y:e.clientY,at:p,value,width:r.width,height:r.height,offsetX:r.left-parent.left,offsetY:r.top-parent.top};h.setPointerCapture(e.pointerId);};
    h.onpointermove=e=>{if(!drag)return;const step=$('design-snap').checked?2:0.1;const snap=v=>Math.max(-20,Math.min(20,Math.round(v/step)*step));const x=snap(drag.at.x+(e.clientX-drag.x)/drag.width*100),y=snap(drag.at.y+(e.clientY-drag.y)/drag.height*100);h.style.left=drag.offsetX+(bases[key][0]+x)*drag.width/100+'px';h.style.top=drag.offsetY+(bases[key][1]+y)*drag.height/100+'px';h.dataset.x=x;h.dataset.y=y;};
    h.onpointerup=action(async()=>{if(!drag)return;const before=copy(api.state()),next=copy(drag.value);next.layout={...(next.layout||{}),[key]:{x:Number(h.dataset.x??drag.at.x),y:Number(h.dataset.y??drag.at.y)}};drag=null;delete h.dataset.x;delete h.dataset.y;await replace(next);undo.push(before);redo=[];buttons();positions();message('位置已调整；统一 2% 网格可帮助保持对齐。');});h.onpointercancel=()=>{drag=null;positions();};
  }
  function positions(){const layout=api.state().layout||{},r=(slug==='poster'?document.getElementById('poster'):surface).getBoundingClientRect(),parent=surface.getBoundingClientRect(),x=r.left-parent.left,y=r.top-parent.top;safe.style.inset='auto';safe.style.left=x+r.width*.05+'px';safe.style.top=y+r.height*.05+'px';safe.style.width=r.width*.9+'px';safe.style.height=r.height*.9+'px';for(const {key,h}of handles){h.hidden=!!document.fullscreenElement||!$('design-drag').checked;h.style.left=x+(bases[key][0]+(layout[key]?.x||0))*r.width/100+'px';h.style.top=y+(bases[key][1]+(layout[key]?.y||0))*r.height/100+'px';}}
  $('design-drag').onchange=positions;$('design-safe').onchange=()=>safe.hidden=!!document.fullscreenElement||!$('design-safe').checked;$('design-reset').onclick=action(async()=>{const before=copy(api.state()),next=copy(before);next.layout={};await replace(next);undo.push(before);redo=[];positions();buttons();});
  $('design-ratio').onchange=()=>{const value=$('design-ratio').value;if(slug==='display'){surface.style.aspectRatio=value==='native'?'':value;surface.style.minHeight=value==='native'?'':'0';surface.style.height=value==='native'?'':'auto';}else{surface.style.maxWidth=value==='native'?'':'min(100%, 500px)';surface.style.aspectRatio=value==='native'?'':value;message(value==='native'?'已恢复原始预览':'这是容器比例检查，不改变导出尺寸；要改变海报比例请使用“画布比例”。');}};
